/**
 * Identity for real NFL teams and players: colors, logos, headshots, defensive
 * personnel.
 *
 * Two tiers, deliberately:
 *   1. A curated snapshot generated by scripts/fetch-nfl-data.mjs ships in the
 *      bundle, so the first paint always has real names, colors and faces even
 *      with no network.
 *   2. refreshIdentity() then asks ESPN for today's version — mainly for injury
 *      status and mid-season team changes — caches it, and merges it on top.
 *      Every failure path falls back to tier 1 rather than surfacing an error;
 *      stale identity is much better than a blank card.
 */
import teamsData from '@/data/nfl/teams.json';
import poolIdentityData from '@/data/nfl/pool-identity.json';
import { logWarn } from '@/lib/logger';

export interface NflTeam {
  abbr: string;
  espnId: string;
  name: string;
  nickname: string;
  location: string;
  color: string;
  altColor: string;
  logo: string;
}

export interface PlayerIdentity {
  poolId: string;
  poolName: string;
  poolTeam: string;
  /** 'exact' | 'fuzzy(n)' | 'moved' — anything but 'exact' means the pool data disagrees with ESPN. */
  confidence: string;
  note: string | null;
  espnId: string;
  name: string;
  team: string;
  position: string;
  jersey: string | null;
  age: number | null;
  experience: number | null;
  heightInches: number | null;
  weightPounds: number | null;
  college: string | null;
  headshot: string | null;
  status: string | null;
  injury: { status: string | null; detail: string | null } | null;
}

export interface DefenseUnits {
  dl: PlayerIdentity[];
  lb: PlayerIdentity[];
  db: PlayerIdentity[];
}

const ESPN_API = 'https://site.api.espn.com/apis/site/v2/sports/football/nfl';
const CACHE_KEY = 'draft-vault:nfl-identity:v1';
const CACHE_TTL_MS = 12 * 60 * 60 * 1000;
const LIVE_TIMEOUT_MS = 6000;

/** Abbreviations the auction pool spells differently from ESPN. */
const TEAM_ALIASES: Record<string, string> = {
  JAC: 'JAX',
  AZ: 'ARI',
  WAS: 'WSH',
  LA: 'LAR',
  SD: 'LAC',
  OAK: 'LV',
  STL: 'LAR',
};

export const canonicalTeam = (abbr: string): string => TEAM_ALIASES[abbr] ?? abbr;

const teams = new Map<string, NflTeam>(
  (teamsData.teams as NflTeam[]).map((team) => [team.abbr, team])
);

const identities = new Map<string, PlayerIdentity>(
  (poolIdentityData.players as PlayerIdentity[]).map((player) => [player.poolId, player])
);

/** Live overrides keyed by ESPN athlete id, merged over the bundled snapshot. */
let liveOverrides = new Map<string, Partial<PlayerIdentity>>();

// ---------------------------------------------------------------------------
// reads
// ---------------------------------------------------------------------------

export const getTeam = (abbr: string): NflTeam | undefined => teams.get(canonicalTeam(abbr));

export const allTeams = (): NflTeam[] => [...teams.values()];

export const getIdentity = (poolId: string): PlayerIdentity | undefined => {
  const base = identities.get(poolId);
  if (!base) return undefined;
  const live = liveOverrides.get(base.espnId);
  return live ? { ...base, ...live } : base;
};

/** A team's colors, falling back to neutral ink so a card never renders unstyled. */
export const teamColors = (abbr: string): { primary: string; secondary: string } => {
  const team = getTeam(abbr);
  return { primary: team?.color ?? '#4a5568', secondary: team?.altColor ?? '#1a202c' };
};

export const teamLogo = (abbr: string): string | undefined => {
  const team = getTeam(abbr);
  if (!team) return undefined;
  return embedded().logos?.[team.abbr] ?? team.logo;
};

/**
 * Optional bundle of embedded images, injected by fully self-contained builds
 * (`npm run build:single`) so a page with no network still shows faces and
 * logos. Absent in a normal build, where the CDN serves them.
 */
interface EmbeddedAssets {
  headshots?: Record<string, string>;
  logos?: Record<string, string>;
}

const embedded = (): EmbeddedAssets =>
  (globalThis as { __DV_ASSETS__?: EmbeddedAssets }).__DV_ASSETS__ ?? {};

/**
 * ESPN's image combiner, which resizes server-side — full-size headshots are
 * ~240 KB each and there are sixty of them on the board at once.
 */
export const headshotUrl = (identity: Pick<PlayerIdentity, 'espnId'>, width = 200): string =>
  embedded().headshots?.[identity.espnId] ??
  `https://a.espncdn.com/combiner/i?img=/i/headshots/nfl/players/full/${identity.espnId}.png&w=${width}&h=${Math.round(
    width * 0.73
  )}&scale=crop&cquality=80`;

/**
 * Real defensive personnel for a team. Loaded on demand: the full league's
 * defensive units are ~115 KB and only matter once a defense profile opens.
 */
export const loadDefenseUnits = async (abbr: string): Promise<DefenseUnits | undefined> => {
  const module = await import('@/data/nfl/defense-units.json');
  const byTeam = (module.default ?? module).teams as Record<string, DefenseUnits>;
  return byTeam[canonicalTeam(abbr)];
};

/** Pool entries whose identity ESPN disagrees with — surfaced in the UI, not hidden. */
export const identityWarnings = (): PlayerIdentity[] =>
  [...identities.values()].filter((player) => player.confidence !== 'exact');

export const snapshotMeta = (): { season: number | null; generatedAt: string } => ({
  season: (teamsData as { season?: number }).season ?? null,
  generatedAt: (teamsData as { generatedAt?: string }).generatedAt ?? '',
});

// ---------------------------------------------------------------------------
// live refresh
// ---------------------------------------------------------------------------

interface CachedLive {
  fetchedAt: number;
  overrides: Array<[string, Partial<PlayerIdentity>]>;
}

const readCache = (): CachedLive | null => {
  try {
    const raw = localStorage.getItem(CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CachedLive;
    if (Date.now() - parsed.fetchedAt > CACHE_TTL_MS) return null;
    return parsed;
  } catch {
    return null; // private mode, quota, corrupt entry — all mean "no cache"
  }
};

const writeCache = (cache: CachedLive): void => {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
  } catch {
    /* storage unavailable; the refresh still applies for this session */
  }
};

const fetchJSON = async (url: string, signal: AbortSignal): Promise<unknown> => {
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`${url} -> ${res.status}`);
  return res.json();
};

interface EspnAthlete {
  id: string;
  fullName?: string;
  position?: { abbreviation?: string };
  status?: { name?: string };
  injuries?: Array<{ status?: string; details?: { type?: string } }>;
  team?: { abbreviation?: string };
}

/**
 * Refreshes injury status and team for the pool's players from ESPN.
 *
 * Only the teams the pool actually references are fetched, so this is a handful
 * of requests rather than all thirty-two. Resolves to the number of players
 * updated, or 0 when the network is unavailable — never rejects.
 */
export const refreshIdentity = async (): Promise<number> => {
  const cached = readCache();
  if (cached) {
    liveOverrides = new Map(cached.overrides);
    return liveOverrides.size;
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), LIVE_TIMEOUT_MS);

  try {
    const wanted = new Map<string, Set<string>>(); // espn team id -> athlete ids
    for (const player of identities.values()) {
      const team = getTeam(player.team);
      if (!team) continue;
      const bucket = wanted.get(team.espnId) ?? new Set<string>();
      bucket.add(player.espnId);
      wanted.set(team.espnId, bucket);
    }

    const overrides = new Map<string, Partial<PlayerIdentity>>();
    const rosters = await Promise.all(
      [...wanted.keys()].map((espnTeamId) =>
        fetchJSON(`${ESPN_API}/teams/${espnTeamId}/roster`, controller.signal).catch(() => null)
      )
    );

    for (const roster of rosters) {
      if (!roster) continue;
      const payload = roster as {
        team?: { abbreviation?: string };
        athletes?: Array<{ items?: EspnAthlete[] }>;
      };
      const teamAbbr = payload.team?.abbreviation;
      for (const group of payload.athletes ?? []) {
        for (const athlete of group.items ?? []) {
          const injury = athlete.injuries?.[0];
          overrides.set(athlete.id, {
            team: teamAbbr ?? undefined,
            status: athlete.status?.name ?? null,
            injury: injury
              ? { status: injury.status ?? null, detail: injury.details?.type ?? null }
              : null,
          });
        }
      }
    }

    if (overrides.size) {
      liveOverrides = overrides;
      writeCache({ fetchedAt: Date.now(), overrides: [...overrides.entries()] });
    }
    return overrides.size;
  } catch (error) {
    logWarn('Live NFL identity refresh unavailable; using bundled snapshot', {
      component: 'nflIdentity',
      reason: error instanceof Error ? error.message : String(error),
    });
    return 0;
  } finally {
    clearTimeout(timeout);
  }
};
